// Included inside leapfrog.rs in a research-only source copy.
pub(crate) fn payload_model_probe(){
 use alloy_primitives::U256;
 use ruint::aliases::U512;
 use sha3::{Shake256,digest::{Update,ExtendableOutput}};
 use crate::circuit::{analyze_ops,QubitOrBit};
 let mut c=Builder::new();let p0=c.alloc_qubits(256);let p1=c.alloc_qubits(256);let letter=c.alloc_qubits(5);let _padding=c.alloc_qubits(1105-517);c.cx_pairs(&p0,&p1);cells::mod_halve(&mut c,&p1);let seed_at=c.op_count();let mut pay=[p0.clone(),p1.clone()];y15::fwd_tick0_one(&mut c,&letter,&mut pay);let ops=c.take_ops();crate::write_ops(&ops,std::path::Path::new("../t0-probe-ops.bin")).unwrap();let(nq,nb,_,_)=analyze_ops(ops.iter());let fs=go_fs("GO_FG_P");let p=super::SECP256K1_P;let f=0x1000003d1i128;
 let mut values=vec![U256::ZERO,U256::from(1),U256::from(2),U256::from(f as u64-1),U256::from(f as u64),U256::from(f as u64+1),(U256::from(1)<<fs)-U256::from(1),(U256::from(1)<<fs)+U256::from(1),p-U256::from(1)];for i in [31,32,55,56,57,63,127,200,254,255]{values.push(U256::from(1)<<i);values.push((U256::from(1)<<i)-U256::from(1));}
 let cases:Vec<_>=values.iter().flat_map(|&t|(0..32usize).map(move|bits|(t,bits))).collect();let qr=|q:&[QubitId]|q.iter().map(|q|QubitOrBit::Qubit(*q)).collect::<Vec<_>>();let(reg0,reg1,lr)=(qr(&p0),qr(&p1),qr(&letter));let big=|v:U256|{let a=v.as_limbs();U512::from_limbs([a[0],a[1],a[2],a[3],0,0,0,0])};let lowmask:U256=(U256::from(1)<<fs)-U256::from(1);let mask57:U256=(U256::from(1)<<57)-U256::from(1);let mut seed_bad=0;let mut generic_bad=0;let mut observed=0;
 for(batch,rows)in cases.chunks(64).enumerate(){let mut h=Shake256::default();h.update(b"source-t0-seed-contract-v1");h.update(&(batch as u64).to_le_bytes());let mut rng=h.finalize_xof();let mut rr=rng.clone();let mut s=super::observed_sim::Simulator::new(nq as usize,nb as usize,&mut rng);let mut reference=crate::sim::Simulator::new(nq as usize,nb as usize,&mut rr);for(lane,(t,bits))in rows.iter().enumerate(){for sim in [&mut s]{sim.set_register(&reg0,*t,lane);sim.set_register(&lr,U256::from(*bits),lane);}reference.set_register(&reg0,*t,lane);reference.set_register(&lr,U256::from(*bits),lane);}
 let mut seeds=Vec::new();s.apply_observed(ops.iter(),|idx,s,_,_|{if idx==seed_at{seeds=(0..rows.len()).map(|lane|s.get_register(&reg1,lane)).collect();}});reference.apply_iter(ops.iter());assert_eq!(s.qubits,reference.qubits);assert_eq!(s.bits,reference.bits);assert_eq!(s.phase,reference.phase);assert_eq!(s.stats.toffoli_gates,reference.stats.toffoli_gates);assert_eq!(seeds.len(),rows.len());
 for(lane,(t,bits))in rows.iter().enumerate(){let odd=t.bit(0);let corrected=if odd{(*t&!lowmask)|(t.wrapping_sub(U256::from(f as u64))&lowmask)}else{*t};let expect_seed=(corrected>>1)|(U256::from(odd as u64)<<255);assert_eq!(seeds[lane],expect_seed,"seed finite subtraction");let ideal_half=if odd{(*t>>1)+(p>>1)+U256::from(1)}else{*t>>1};let seed_wrong=expect_seed!=ideal_half;seed_bad+=usize::from(seed_wrong);
 let n0=bits&1;let n1=(bits>>1)&1;let n2=(bits>>2)&1;let extra=bits>>3;let a0=n2&(1-n1);let a1=a0&n0;let j:usize=if n1!=0{1}else if a0!=0{0}else{2};let sc=n0^a0;let tc=n2^a0^a1;let b=seeds[lane];let x:U512=(big(if tc!=0{!*t}else{*t})<<j)+big(if sc!=0{!b}else{b});let limbs=x.as_limbs();let l=U256::from_limbs([limbs[0],limbs[1],limbs[2],limbs[3]]);let e=limbs[4]as i128;let nm=(sc+(tc<<j))as i128;let shift=3+extra;let d=1i128<<shift;let a=l.as_limbs()[0]as i128+e+(e-nm)*(f-1);let digit=(0..d).find(|m|(a-m*f).rem_euclid(d)==0).unwrap();let constant=e+(e-nm-digit)*(f-1);let low=(l&mask57).as_limbs()[0]as i128;let w=(l&!mask57)|U256::from((low+constant).rem_euclid(1i128<<57)as u64);let expected:U256=(w>>shift)|(U256::from(digit as u64)<<(256-shift));let got=s.get_register(&reg0,lane);assert_eq!(got,expected,"source one-add output batch{batch} lane{lane}");assert_eq!(s.get_register(&reg1,lane),b,"source payload preserved");let total=observed+lane;if total==641{eprintln!("T0_CLEAN_WITNESS case={total} T={t:#x} seed_actual={b:#x} seed_ideal={ideal_half:#x} signs={n0},{n1},{n2} extra={extra} actual={got:#x} source_formula={expected:#x}");}if seed_wrong&&seed_bad<=8{eprintln!("SEED_HALF_WITNESS case={total} T={t:#x} fs={fs} actual={b:#x} ideal={ideal_half:#x} signs={n0},{n1},{n2} extra={extra}");}}
 observed+=rows.len();}
 eprintln!("T0_SOURCE_CONTRACT_PASS shots={observed} seed_width={fs} raw_source_seed_and_oneadd=true protected_all_qubits=true all_bits=true phase=true toffolis=true seed_half_outside_ideal={seed_bad} score=NONE");
}
